INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('034cb385-cf16-5975-b93e-9b37d71e81b5', '670588ba-52d1-517e-91ed-253da7cc3297', 'en', $h$Automatic AdBlue Nozzle – 13660$h$, $h$automatic-adblue-nozzle-13660$h$, NULL, $h$<div> <div><p><strong>Why the 13660 Automatic AdBlue Nozzle?</strong></p><p>This fuel nozzle works with different fluids such as AdBlue, fuel and oil. Manufactured entirely from stainless material, this nozzle offers long service life with its corrosion-resistant stainless steel body and provides a 3/4″ inlet. It shuts off automatically when the tank is full or when fuel reaches the outlet hole. Its automatic system operates on pump pressure alone. Thanks to its high accuracy and compact size, you can carry it comfortably. The filter at the inlet prevents contamination during fuel transfer. Use this nozzle with different pumps and flow meters in many applications such as refueling engines, cars and tractors.</p></div> </div>$h$, NULL, $h$Automatic AdBlue Nozzle – 13660 | HD Marine$h$, $h$Why the 13660 Automatic AdBlue Nozzle? This fuel nozzle works with different fluids such as AdBlue, fuel and oil. Manufactured entirely from stainless…$h$, 'auto') ON CONFLICT DO NOTHING;
