INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('b7860b42-b5bb-5738-8123-1416b4e02d5e', '8aae8e73-fb13-581f-8b1f-f690f82503a5', 'en', $h$Oil Suction Hose – 0776$h$, $h$oil-suction-hose-0776$h$, NULL, $h$<div> <div><p><strong>Why the 0776 Oil Suction Hose?</strong></p><p>We can manufacture these systems, used with IBC and wall-mounted pumps, in different diameters and lengths, so they perfectly match your needs. The built-in filter protects your pump from contamination and extends equipment life. The integrated check valve guarantees one-way flow and prevents backflow. These features offer a reliable solution for efficient, uninterrupted fluid transfer.</p></div> </div>$h$, NULL, $h$Oil Suction Hose – 0776 | HD Marine$h$, $h$Why the 0776 Oil Suction Hose? We can manufacture these systems, used with IBC and wall-mounted pumps, in different diameters and lengths, so they…$h$, 'auto') ON CONFLICT DO NOTHING;
