INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('3be772e3-a11a-59d8-b323-18dd61416097', '05b6ccab-b0f5-5ebf-af48-e41933b68fe4', 'en', $h$Tarus 7442 Foam Spray Gun$h$, $h$tarus-7442-foam-spray-gun$h$, NULL, $h$<div> <div><div><strong>Technical Specifications</strong></div><div>Working pressure: 15 Bar</div><div>Maximum water temperature: 50°C</div><div>Length: 60 cm</div><div>Tube type: Aluminium</div><div>Nozzle type: Flat fan</div><div>Inlet: 1/2″ F</div><div>Foam spray nozzle included</div><div><strong><br/>Product Features</strong></div><div>Specially manufactured for foam spray tanks, this foam spray gun has an ergonomic body and barrel design that prevents fatigue while working and minimizes vibration.</div></div> </div>$h$, NULL, $h$Tarus 7442 Foam Spray Gun | HD Marine$h$, $h$Technical Specifications Working pressure: 15 Bar Maximum water temperature: 50°C Length: 60 cm Tube type: Aluminium Nozzle type: Flat fan Inlet: 1/2″ F…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('53d18bc1-6b7a-5ea3-b23c-a2192f96eda8', '8f698e5a-8be9-5610-86ff-44d768253dbe', 'en', $h$Tarus 7441 Liquid Spray Gun$h$, $h$tarus-7441-liquid-spray-gun$h$, NULL, $h$<div> <div><div><strong>Technical Specifications</strong></div><div>Working pressure: 15 Bar</div><div>Maximum water temperature: 50°C</div><div>Length: 60 cm</div><div>Tube type: Aluminium</div><div>Nozzle type: Flat fan</div><div>Inlet: 1/2″ F</div><div>Liquid spray nozzle included<p><strong>Product Features<br/></strong>Specially manufactured for liquid spray tanks, this spray gun has an ergonomic body and barrel design that prevents fatigue while working and minimizes vibration.</p></div></div> </div>$h$, NULL, $h$Tarus 7441 Liquid Spray Gun | HD Marine$h$, $h$Technical Specifications Working pressure: 15 Bar Maximum water temperature: 50°C Length: 60 cm Tube type: Aluminium Nozzle type: Flat fan Inlet: 1/2″ F…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('e9b9b6ca-b339-5868-8af2-4d353c797648', '0921d0a8-9df8-5930-b168-afa5983db870', 'en', $h$Electric Sump Oil Extraction Pump 9 L – 6910$h$, $h$electric-sump-oil-extraction-pump-9-l-6910$h$, $h$Aro® Compatible Spare Part$h$, $h$<div> <div><p>Aro® first introduced its air-operated double diaphragm pump in the eighties in Bryan, Ohio (United States). Today, ARO® is part of Ingersoll Rand Corp. and is one of the leading AODD Pump brands.</p></div> </div><div> <div><p>ARO® air-operated diaphragm pumps have the capacity to transfer a wide range of viscous fluids and ensure stall-free, ice-free operation. Their unbalanced air valve design prevents the stalling problems associated with other pumps. Quick-dump exhaust valves direct cold exhaust air away from ice-prone components and prevent freezing. Depending on the type of fluid to be transferred, the pump section is available in piston pump packages with multiple configurations, including single-body, two-body and heavy-duty two-body versions.</p><p>ARO® diaphragm pumps, with their cost-effectiveness and reliable construction, are a good choice for industrial and chemical applications. Their bolted, leak-free construction eliminates cross-contamination and improves operator safety. The modular design, reduced part count and easy-to-use repair kits also minimize repair time when needed.</p><p>HD Marine brings you reliable, high-quality spare parts compatible with double diaphragm (AODD) pumps. HD Marine provides replacement support for many parts of your choice and is your address for Aro spare parts such as<strong> valve balls, valve seats, diaphragms, gaskets, clamp bands, mufflers, pistons and valve rings</strong>.</p><p>In the event of any failure or maintenance on diaphragm pumps, you can select Aro-compatible products individually on the HD Marine website, or access the service/repair kit from the <strong>Aro Service Kits</strong> section, which combines screws, gaskets and many types of rings. Service kits come in two types: a wet kit for the wet end of your pneumatic double diaphragm pump, and a kit used for maintenance and repair of the air side of your air-operated double diaphragm pump. Since these two kits contain different products, you should make your choice by considering which products you need and where you will use them.</p><p>If you want to purchase products individually outside the <strong>Aro Service Kits</strong>, you can also access <strong>Aro gaskets, Aro rings, Aro valve balls, Aro valve seats, Aro hardware and Aro diaphragms</strong>. However, keep in mind that the application area in which each industry uses its pumps, and the appropriate Aro spare part for that area, will vary. Based on your specific application needs such as chemical compatibility, temperature and sealing capacity, HD Marine offers its customers high-quality, widely used and preferred materials and products such as <strong>Santoprene, Hytrel, N-fit, PTFE and Neoprene</strong> in pump parts.</p></div> </div>$h$, NULL, $h$Electric Sump Oil Extraction Pump 9 L – 6910 | HD Marine$h$, $h$Aro® first introduced its air-operated double diaphragm pump in the eighties in Bryan, Ohio (United States). Today, ARO® is part of Ingersoll Rand Corp…$h$, 'auto') ON CONFLICT DO NOTHING;
