INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('1a127974-e040-5bc2-9bda-2f67caf6c784', '60d28b8a-30ae-5465-90bc-d79372505bf8', 'en', $h$What is an airless paint sprayer?$h$, $h$<div> <p>An airless paint sprayer is professional painting equipment that sprays paint at high pressure, providing even and fast coverage on the surface.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('07934aa6-02d7-5027-8899-b1fbdca3baf7', 'b15d5aa8-0fb8-5000-9c6c-15407c52b129', 'en', $h$What does “airless” mean?$h$, $h$<div> <p>Airless means without air, and indicates that no compressed air is used to spray the paint; this allows the paint to be atomized at higher pressure.</p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('a2ee4887-0c84-5560-bf30-ab9f59d1c1ab', 'e22f7819-4dc0-5c17-b492-1822c345fcb9', 'en', $h$Where are airless machines used?$h$, $h$<div> <p>They are used in many areas such as large-surface painting, industrial painting, marine and ship surfaces, and floor applications. </p> </div>$h$) ON CONFLICT DO NOTHING;
INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES ('7eac9a7c-7c9e-56d2-b1c2-03aff522680b', '4eb26d41-df6b-5e0f-b24c-61b831e83353', 'en', $h$What are the advantages?$h$, $h$<div> <p>Airless machines offer the advantages of fast coverage, high efficiency, low paint waste and even surface coverage.</p> </div>$h$) ON CONFLICT DO NOTHING;
